// verify drives the handler contract through the fixture provider's route and
// returns an empty string on success.
func verify() string {
	opened := ohrats_rc_websocket_handler.Open(ohrats_rc_websocket_types.OpenRequest{
		Route: "/fixture/socket",
		Query: "device=fixture",
		Headers: []ohrats_rc_websocket_types.Header{{
			Name:  "sec-websocket-protocol",
			Value: "fixture.v1",
		}},
		Principal: witTypes.Some("fixture-user"),
	})
	if opened.IsErr() {
		return opened.Err()
	}
	if opened.Ok().IsNone() {
		return "fixture route declined"
	}
	session := opened.Ok().Some()
	defer session.Session.Drop()
	if session.Limits.MaxMessageBytes == 0 {
		return "invalid limits"
	}
	if result := session.Session.Inbound(ohrats_rc_websocket_types.MakeInboundMessage(
		ohrats_rc_websocket_types.MakeMessagePing([]uint8{1, 2}),
	)); result.IsErr() {
		return result.Err()
	}
	pong := session.Session.Poll(2)
	if pong.IsErr() {
		return pong.Err()
	}
	if frames := pong.Ok().Frames; len(frames) != 1 ||
		frames[0].Tag() != ohrats_rc_websocket_types.Outbound_Message ||
		frames[0].Message().Tag() != ohrats_rc_websocket_types.Message_Pong ||
		len(frames[0].Message().Pong()) != 2 ||
		frames[0].Message().Pong()[0] != 1 ||
		frames[0].Message().Pong()[1] != 2 {
		return "ping/pong semantics failed"
	}
	if result := session.Session.Inbound(ohrats_rc_websocket_types.MakeInboundMessage(
		ohrats_rc_websocket_types.MakeMessageBinary([]uint8{3, 4}),
	)); result.IsErr() {
		return result.Err()
	}
	if result := session.Session.Inbound(ohrats_rc_websocket_types.MakeInboundMessage(
		ohrats_rc_websocket_types.MakeMessageText("metadata"),
	)); result.IsErr() {
		return result.Err()
	}
	if result := session.Session.Inbound(ohrats_rc_websocket_types.MakeInboundPeerClose(
		witTypes.Some(ohrats_rc_websocket_types.CloseFrame{Code: 1000, Reason: "done"}),
	)); result.IsErr() {
		return result.Err()
	}
	closed := session.Session.Poll(4)
	if closed.IsErr() {
		return closed.Err()
	}
	if frames := closed.Ok().Frames; len(frames) != 1 ||
		frames[0].Tag() != ohrats_rc_websocket_types.Outbound_Close ||
		frames[0].Close().Code != 1000 {
		return "close semantics failed"
	}
	session.Session.Close("fixture complete")
	return ""
}
